from collections import OrderedDict
class LRU:
    def __init__(self, capacity):
        if capacity <= 0: raise ValueError('capacity')
        self.c = capacity; self.d = OrderedDict()
    def get(self, k):
        if k not in self.d: return None
        self.d.move_to_end(k); return self.d[k]
    def put(self, k, v):
        if k in self.d: self.d.move_to_end(k)
        self.d[k] = v
        if len(self.d) > self.c: self.d.popitem(last=False)

import csv, io
def sum_column(text, col):
    reader = csv.DictReader(io.StringIO(text))
    if col not in (reader.fieldnames or []):
        raise KeyError(col)
    total = 0.0
    for r in reader:
        v = r.get(col)
        if v is None: continue
        try: total += float(v)
        except (TypeError, ValueError): continue
    return total

class Bucket:
    def __init__(self, rate, capacity, clock):
        self.rate, self.cap, self.clock = rate, capacity, clock
        self.tokens = capacity; self.t = clock()
    def allow(self):
        now = self.clock()
        self.tokens = min(self.cap, self.tokens + (now - self.t) * self.rate)
        self.t = now
        if self.tokens >= 1:
            self.tokens -= 1; return True
        return False

def flatten(d, sep='.'):
    out = {}
    def walk(prefix, obj):
        for k, v in obj.items():
            key = f'{prefix}{sep}{k}' if prefix else str(k)
            if isinstance(v, dict): walk(key, v)
            else: out[key] = v
    walk('', d)
    return out

