def names(e):
    # whole tokens: 'c' is a substring of 'cycle', so a message naming the
    # wrong node would otherwise satisfy the assertion
    return set(re.findall(r'[A-Za-z_][A-Za-z_0-9]*', str(e)))
try:
    toposort({'a': ['b'], 'b': ['a']}); assert False
except ValueError as e:
    assert names(e) & {'a', 'b'}, str(e)
# 'd' is blocked BY the cycle but is not IN it; naming it is not naming the cycle
try:
    toposort({'b': ['c'], 'c': ['b'], 'd': ['b']}); assert False
except ValueError as e:
    assert names(e) & {'b', 'c'}, str(e)
