def merge(ranges):
    for s, e in ranges:
        if s > e: raise ValueError((s, e))
    out = []
    for s, e in sorted(ranges):
        if out and s <= out[-1][1] + 1:
            out[-1] = (out[-1][0], max(out[-1][1], e))
        else:
            out.append((s, e))
    return out
